17	        int low = 0;
18	        int high = sortedValues.length - 1;
19	
20	        while (low <= high) {
21	            int mid = low + (high - low) / 2;
22	            int midValue = sortedValues[mid];
23	
24	            if (midValue == target) {
25	                return mid;
